from solution import Entry, Report, solve

assert solve([]) == Report(0, 0, 0), 'fixture 0'
assert solve([Entry(11, 15)]) == Report(1, 1, 0), 'fixture 1'
assert solve([Entry(3, 8), Entry(6, 12)]) == Report(2, 5, 0), 'fixture 2'
assert solve([Entry(0, 2), Entry(1, 6), Entry(10, 13)]) == Report(2, 8, 1), 'fixture 3'
assert solve([Entry(3, 6), Entry(5, 10), Entry(6, 13), Entry(7, 8)]) == Report(3, 20, 1), 'fixture 4'
assert solve([Entry(0, 5), Entry(4, 5), Entry(6, 7), Entry(8, 15), Entry(9, 12)]) == Report(2, 22, 3), 'fixture 5'
assert solve([Entry(0, 2), Entry(1, 8), Entry(5, 9), Entry(7, 13), Entry(9, 11), Entry(10, 14)]) == Report(3, 37, 3), 'fixture 6'
assert solve([Entry(0, 1), Entry(0, 3), Entry(1, 5), Entry(5, 12), Entry(6, 12), Entry(7, 14), Entry(11, 12)]) == Report(4, 68, 3), 'fixture 7'
assert solve([Entry(2, 3), Entry(3, 9), Entry(7, 8), Entry(9, 11), Entry(9, 12), Entry(10, 14), Entry(10, 17), Entry(11, 12)]) == Report(4, 77, 4), 'fixture 8'
assert solve([Entry(0, 4), Entry(2, 9), Entry(3, 4), Entry(4, 6), Entry(4, 11), Entry(5, 7), Entry(5, 9), Entry(6, 11), Entry(10, 11)]) == Report(5, 118, 4), 'fixture 9'
assert solve([Entry(1, 7), Entry(2, 7), Entry(2, 4), Entry(4, 6), Entry(5, 8), Entry(7, 8), Entry(8, 11), Entry(8, 11), Entry(9, 12), Entry(11, 14)]) == Report(4, 112, 6), 'fixture 10'
assert solve([Entry(0, 2), Entry(2, 8), Entry(3, 7), Entry(4, 5), Entry(6, 12), Entry(6, 8), Entry(7, 9), Entry(7, 11), Entry(8, 14), Entry(9, 14), Entry(9, 14)]) == Report(5, 187, 6), 'fixture 11'
assert solve([Entry(1, 8), Entry(1, 6), Entry(3, 8), Entry(4, 6), Entry(5, 12), Entry(5, 7), Entry(6, 10), Entry(6, 12), Entry(8, 9), Entry(9, 12), Entry(9, 10), Entry(11, 15)]) == Report(6, 213, 6), 'fixture 12'
assert solve([Entry(1, 3)]) == Report(1, 1, 0), 'fixture 13'
assert solve([Entry(0, 4), Entry(2, 5)]) == Report(2, 5, 0), 'fixture 14'
assert solve([Entry(7, 10), Entry(7, 9), Entry(8, 10)]) == Report(3, 14, 0), 'fixture 15'
assert solve([Entry(0, 3), Entry(4, 9), Entry(8, 12), Entry(8, 15)]) == Report(3, 21, 1), 'fixture 16'
assert solve([Entry(6, 9), Entry(8, 9), Entry(10, 12), Entry(10, 11), Entry(10, 14)]) == Report(3, 31, 2), 'fixture 17'
assert solve([Entry(3, 7), Entry(4, 10), Entry(5, 9), Entry(9, 16), Entry(9, 16), Entry(10, 12)]) == Report(3, 45, 3), 'fixture 18'
assert solve([Entry(0, 6), Entry(2, 9), Entry(3, 8), Entry(3, 5), Entry(8, 13), Entry(8, 10), Entry(10, 11)]) == Report(4, 67, 3), 'fixture 19'
assert solve([Entry(2, 9), Entry(3, 5), Entry(4, 9), Entry(5, 7), Entry(7, 14), Entry(8, 15), Entry(10, 11), Entry(10, 12)]) == Report(4, 87, 4), 'fixture 20'
assert solve([Entry(0, 1), Entry(0, 2), Entry(0, 3), Entry(3, 4), Entry(3, 4)]) == Report(3, 28, 2), 'fixture 21'
assert solve([Entry(0, 5), Entry(1, 3), Entry(3, 6), Entry(5, 7)]) == Report(2, 15, 2), 'fixture 22'
